using System;
using System.Collections;
using System.Collections.Generic;
using System.Text.Json.Serialization;

namespace bankingonaspdotnet.Domain;

/// <summary>
/// TransactionDirection enumerator class
/// </summary>
[JsonConverter(typeof(JsonStringEnumConverter))]

public enum TransactionDirection
{
    Credit = 1, Debit = 2
}

/// <summary>
/// Extension of capabilities for the TransactionDirection enum
/// </summary>
public static class TransactionDirectionExtensions
{
    //************************************************************************
    // static implementations
    //************************************************************************
    public static List<TransactionDirection> GetValues()
    {
        return Enum.GetValues<TransactionDirection>().ToList();
    }

    public static TransactionDirection GetDefaultValue()
    {
        return Enum.GetValues<TransactionDirection>().First();
    }

    public static TransactionDirection WhichOne(string name)
